  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "承载着今日所有的那悲伤"
        },
        {
          "id": "V2-02",
          "zh": "运送来明日里所有的欢悦"
        },
        {
          "id": "V2-03",
          "zh": "全部都被那风儿给带走"
        },
        {
          "id": "V2-04",
          "zh": "向着该去的地方"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "今日的 载着悲伤"
        },
        {
          "id": "V2-02",
          "zh": "明天的 运送喜悦"
        },
        {
          "id": "V2-03",
          "zh": "全部 风都带走"
        },
        {
          "id": "V2-04",
          "zh": "前往该去的地方"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "今日的 眼泪和叹息 都收下"
        },
        {
          "id": "V2-02",
          "zh": "明日的 笑声和亮光 都带上"
        },
        {
          "id": "V2-03",
          "zh": "全部 风提着 往远方漂流"
        },
        {
          "id": "V2-04",
          "zh": "去它该去 的地方"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "把今日 悲伤都装进 旧行李"
        },
        {
          "id": "V2-02",
          "zh": "明天的 喜悦还没拆 先上路"
        },
        {
          "id": "V2-03",
          "zh": "全都 风带走 影子也不留"
        },
        {
          "id": "V2-04",
          "zh": "往该去的 那地方"
        }
      ]
    }
  ]
}

